use super::tree_profiles::TreeResource;
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DecoratorScope {
    Tree,
    FallenLog,
    FallenStump,
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum DecoratorKind {
    BeeNest(f64),
    Cocoa(f64),
    LeafVine(f64),
    ShelfMushroom(f64),
    Heart(f64),
    TrunkVine,
    Ground {
        resources: &'static [TreeResource],
        tries: u16,
        height: u8,
        radius: Option<u8>,
    },
    LogMushroom {
        resources: &'static [TreeResource],
        probability: f64,
    },
    Propagule {
        probability: f64,
        minimum_age: u8,
        maximum_age: u8,
        exclusion_horizontal: u8,
        exclusion_vertical: u8,
        clearance: u8,
    },
    Podzol {
        replaceable_tag: &'static str,
        resource: TreeResource,
    },
    PaleMoss {
        ground: f64,
        leaves: f64,
        trunk: f64,
    },
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct DecorationPrescription {
    pub scope: DecoratorScope,
    pub source_kind: &'static str,
    pub configuration_sha256: &'static str,
    pub raw_configuration: &'static str,
    pub kind: DecoratorKind,
}
#[derive(Clone, Copy, Debug)]
pub struct DecorationProfile {
    pub id: &'static str,
    pub source_sha256: &'static str,
    pub prescriptions: &'static [DecorationPrescription],
}
pub fn profile(id: &str) -> Option<&'static DecorationProfile> {
    DECORATION_PROFILES.iter().find(|profile| profile.id == id)
}
